<script>(()=>{const f=document.querySelector('[data-topic-task]'),key=f.dataset.storageKey;try{if(f.dataset.hasErrors!=='true'){const entries=JSON.parse(sessionStorage.getItem(key)||'null');if(entries){f.querySelectorAll('[type=checkbox]').forEach(n=>n.checked=false);f.querySelectorAll('select[multiple]').forEach(n=>Array.from(n.options).forEach(o=>o.selected=false));for(const[n,v]of entries){for(const e of Array.from(f.elements).filter(e=>e.name===n)){if(e.type==='checkbox')e.checked=String(e.value)===String(v);else if(e.multiple)Array.from(e.options).filter(o=>String(o.value)===String(v)).forEach(o=>o.selected=true);else if(!(e.type==='hidden'&&Array.from(f.elements).some(o=>o.name===n&&o.type==='checkbox')))e.value=v;}}}}}catch{}function summarize(){const number=f.querySelector('[name=topic_limit]').value,interval=f.querySelector('[name=interval_value]').value,unit=f.querySelector('[name=interval_unit]'),after=f.querySelector('[name="topic_settings[after]"]'),template=f.querySelector('[name="topic_settings[template_key]"]');document.querySelector('[data-topic-task-summary]').textContent='本轮目标 '+number+' 个专题 · 每 '+interval+' '+unit.selectedOptions[0].textContent+'检查与发布 · '+after.selectedOptions[0].textContent+' · '+template.selectedOptions[0].textContent;}f.addEventListener('input',summarize);f.addEventListener('change',summarize);summarize();const save=()=>{try{sessionStorage.setItem(key,JSON.stringify(Array.from(new FormData(f).entries()).filter(([n])=>!['_token','_method','content_type','topic_config_version'].includes(n))));}catch{}};document.querySelectorAll('[data-preserve-task],[data-task-type]').forEach(a=>a.addEventListener('click',save));f.addEventListener('input',save);f.addEventListener('change',save);f.addEventListener('submit',()=>sessionStorage.removeItem(key));document.querySelector('[data-refresh-options]').addEventListener('click',()=>{save();location.reload();});})();</script>
<script src="{{ asset('admin/topic-editor.js') }}" defer></script>
